<template><div class="page-grid">
<section class="panel"><div class="section-row"><div style="display:flex;align-items:center;gap:14px"><el-avatar :size="58">{{healthProfile.name.slice(0,1)}}</el-avatar><div><h2 style="margin:0 0 5px;font-size:20px">{{healthProfile.name}}</h2><div class="muted small">个人健康档案 · 信息由已关联医疗机构持续更新</div></div></div><el-tag type="success" effect="plain">档案已更新</el-tag></div><div class="kv-list" style="margin-top:24px"><div class="kv-item"><span>性别</span><strong>{{healthProfile.gender}}</strong></div><div class="kv-item"><span>年龄</span><strong>{{healthProfile.age}} 岁</strong></div><div class="kv-item"><span>出生日期</span><strong>{{healthProfile.birthday}}</strong></div><div class="kv-item"><span>血型</span><strong>{{healthProfile.bloodType}}</strong></div><div class="kv-item"><span>身高</span><strong>{{healthProfile.height}} cm</strong></div><div class="kv-item"><span>体重 / BMI</span><strong>{{healthProfile.weight}} kg / {{healthProfile.bmi}}</strong></div></div></section>
<section class="grid-2"><div class="panel"><h3 class="panel-title">当前健康问题</h3><p class="panel-subtitle">依据既往诊疗及健康管理记录汇总</p><div v-for="issue in healthProfile.healthIssues" :key="issue.name" style="padding:14px 0;border-bottom:1px solid var(--line)"><div class="section-row"><strong>{{issue.name}}</strong><el-tag size="small" type="warning" effect="plain">持续关注</el-tag></div><div class="muted small" style="margin-top:7px">首次记录：{{issue.firstRecorded}}</div><div class="muted small" style="margin-top:4px">来源：{{issue.source}}</div></div></div><div class="panel"><h3 class="panel-title">过敏史</h3><p class="panel-subtitle">重要用药安全信息</p><div v-for="allergy in healthProfile.allergies" :key="allergy.name" style="padding:14px 0"><div class="section-row"><strong>{{allergy.name}}</strong><el-tag size="small" type="danger">注意</el-tag></div><div class="muted small" style="margin-top:8px">既往反应：{{allergy.reaction}}</div><div class="muted small" style="margin-top:4px">来源：{{allergy.source}}</div></div></div></section>
<section class="panel"><h3 class="panel-title">当前用药</h3><p class="panel-subtitle">依据最近处方记录汇总</p><el-table :data="healthProfile.medications" style="width:100%"><el-table-column prop="name" label="药品名称" min-width="180"/><el-table-column prop="dose" label="剂量" width="110"/><el-table-column prop="frequency" label="用法" width="130"/><el-table-column prop="lastPrescription" label="最近处方" width="130"/><el-table-column prop="hospital" label="医疗机构" min-width="180"/></el-table></section>
<section class="panel"><h3 class="panel-title">重点健康指标</h3><p class="panel-subtitle">点击指标查看近期记录变化</p><div class="grid-4"><div v-for="item in indicators" :key="item.key" class="metric-card" style="cursor:pointer" @click="selected=item"><div class="label">{{item.name}}</div><div class="metric-value"><strong>{{item.value}}</strong><span>{{item.unit}}</span></div><div class="metric-status" :class="`status-${item.level}`">{{item.status}}</div></div></div></section>
<el-dialog v-model="dialogVisible" :title="selected?`${selected.name} 近期记录`:'指标记录'" width="520px"><div v-if="selected" style="display:grid;gap:12px"><div v-for="point in selected.history" :key="point.date" class="section-row" style="padding:12px 14px;background:#f7f9f9;border-radius:10px"><span class="muted">{{point.date}}</span><strong>{{point.value}} {{selected.unit}}</strong></div></div></el-dialog>
</div></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {healthProfile,indicators} from '@/data/health';const selected=ref<(typeof indicators)[number]|null>(null);const dialogVisible=computed({get:()=>Boolean(selected.value),set:(v)=>{if(!v)selected.value=null}})</script>
